                conn.commit()
            except sqlite3.Error as exc:
                raise OrderError("STORAGE_ERROR", f"failed to commit schema: {exc}", {}) from exc

    # -- transaction helpers ----------------------------------------------

    def _safe_rollback(self, conn: sqlite3.Connection) -> None:
        try:
            conn.rollback()
        except sqlite3.Error:
            pass

    @contextlib.contextmanager
    def _transaction(self):
        conn = self._conn
        try:
            conn.execute("BEGIN IMMEDIATE")
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", f"failed to acquire write lock: {exc}", {}) from exc
        try:
            yield conn
        except OrderError:
            self._safe_rollback(conn)
            raise
        except sqlite3.Error as exc:
            self._safe_rollback(conn)
            raise OrderError("STORAGE_ERROR", f"storage error: {exc}", {}) from exc
        except Exception as exc:
            self._safe_rollback(conn)
            raise OrderError("STORAGE_ERROR", f"unexpected error: {exc}", {}) from exc
        else:
            try:
                conn.commit()
            except sqlite3.Error as exc:
                raise OrderError("STORAGE_ERROR", f"failed to commit: {exc}", {}) from exc

    def _call_clock(self):
        try:
            value = self._clock()
        except Exception as exc:
            raise OrderError("INVALID_DEPENDENCY", f"clock() raised: {exc}", {}) from exc
        if not _is_finite_number(value):
            raise OrderError("INVALID_DEPENDENCY", "clock() must return a finite number", {})
        return value

    def _call_id_factory(self):
        try:
            value = self._id_factory()
        except Exception as exc:
            raise OrderError("INVALID_DEPENDENCY", f"id_factory() raised: {exc}", {}) from exc
        if not _is_nonempty_str(value):
            raise OrderError(
                "INVALID_DEPENDENCY", "id_factory() must return a non-empty, non-whitespace string", {}
            )
        return value

    # -- data access helpers ----------------------------------------------

    def _get_available(self, conn: sqlite3.Connection, sku: str) -> int:
        row = conn.execute("SELECT available FROM stock WHERE sku = ?", (sku,)).fetchone()
        return row["available"] if row is not None else 0

    def _fetch_order_row(self, conn: sqlite3.Connection, order_id: str):
        return conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, amount_cents, "
            "created_at, updated_at FROM orders WHERE order_id = ?",
            (order_id,),
        ).fetchone()

    def _fetch_items(self, conn: sqlite3.Connection, order_id: str) -> list[dict]:
        rows = conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id = ? ORDER BY sku",
            (order_id,),
        ).fetchall()
        return [
            {"sku": row["sku"], "quantity": row["quantity"], "unit_price_cents": row["unit_price_cents"]}
            for row in rows
        ]

    def _order_dict_from_row(self, conn: sqlite3.Connection, row) -> dict:
        items = self._fetch_items(conn, row["order_id"])
        return {
            "order_id": row["order_id"],
            "idempotency_key": row["idempotency_key"],
            "status": row["status"],
            "items": items,
            "total_cents": row["total_cents"],
            "payment_id": row["payment_id"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }

    def _build_order_dict(self, conn: sqlite3.Connection, order_id: str) -> dict:
        row = self._fetch_order_row(conn, order_id)
        return self._order_dict_from_row(conn, row)

    # -- public API ----------------------------------------------

    def set_stock(self, sku: str, quantity: int) -> dict:
        if not _is_nonempty_str(sku):
            raise OrderError("INVALID_INPUT", "sku must be a non-empty, non-whitespace string", {"field": "sku"})
        if not _is_int(quantity) or quantity < 0:
            raise OrderError("INVALID_INPUT", "quantity must be a non-negative integer", {"field": "quantity"})
        with self._transaction() as conn:
            conn.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available = excluded.available",
                (sku, quantity),
            )
        return {"sku": sku, "available": quantity}

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        if not _is_nonempty_str(idempotency_key):
            raise OrderError(
                "INVALID_INPUT",
                "idempotency_key must be a non-empty, non-whitespace string",
                {"field": "idempotency_key"},
            )
        canonical_items = _validate_items(items)
        with self._transaction() as conn:
            row = conn.execute(
                "SELECT order_id FROM orders WHERE idempotency_key = ?", (idempotency_key,)
            ).fetchone()
            if row is not None:
                existing_order_id = row["order_id"]
                existing_items = self._fetch_items(conn, existing_order_id)
                if existing_items == canonical_items:
                    return self._build_order_dict(conn, existing_order_id)
                raise OrderError(
                    "IDEMPOTENCY_CONFLICT",
                    "idempotency_key already used with different items",
                    {"idempotency_key": idempotency_key},
                )
            for item in canonical_items:
                available = self._get_available(conn, item["sku"])
                if available < item["quantity"]:
                    raise OrderError(
                        "INSUFFICIENT_STOCK",
                        f"insufficient stock for sku {item['sku']}",
                        {"sku": item["sku"], "available": available, "requested": item["quantity"]},
                    )
            order_id = None
            for _attempt in range(3):
                candidate = self._call_id_factory()
                exists = conn.execute("SELECT 1 FROM orders WHERE order_id = ?", (candidate,)).fetchone()
                if exists is None:
                    order_id = candidate
                    break
            if order_id is None:
                raise OrderError("ID_COLLISION", "id_factory produced colliding order ids", {})
            now = self._call_clock()
            total_cents = sum(item["quantity"] * item["unit_price_cents"] for item in canonical_items)
            conn.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents, payment_id, "
                "amount_cents, created_at, updated_at) VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)",
                (order_id, idempotency_key, total_cents, now, now),
            )
            for item in canonical_items:
                conn.execute(
                    "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents) VALUES (?, ?, ?, ?)",
                    (order_id, item["sku"], item["quantity"], item["unit_price_cents"]),
                )
                conn.execute(
                    "UPDATE stock SET available = available - ? WHERE sku = ?",
                    (item["quantity"], item["sku"]),
                )
            return self._build_order_dict(conn, order_id)

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        if not _is_nonempty_str(order_id):
            raise OrderError(
                "INVALID_INPUT", "order_id must be a non-empty, non-whitespace string", {"field": "order_id"}
            )
        if not _is_nonempty_str(payment_id):
            raise OrderError(
                "INVALID_INPUT", "payment_id must be a non-empty, non-whitespace string", {"field": "payment_id"}
            )
        if not _is_int(amount_cents) or amount_cents < 0:
            raise OrderError(
                "INVALID_INPUT", "amount_cents must be a non-negative integer", {"field": "amount_cents"}
            )
        with self._transaction() as conn:
            order = self._fetch_order_row(conn, order_id)
            if order is None:
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})
            existing_payment_id = order["payment_id"]
            existing_amount = order["amount_cents"]
            if (
                existing_payment_id is not None
                and existing_payment_id == payment_id
                and existing_amount == amount_cents
            ):
                return self._order_dict_from_row(conn, order)
            other = conn.execute(
                "SELECT 1 FROM orders WHERE payment_id = ? AND order_id != ?", (payment_id, order_id)
            ).fetchone()
            if other is not None:
                raise OrderError(
                    "PAYMENT_CONFLICT", "payment_id already used by another order", {"payment_id": payment_id}
                )
            if existing_payment_id is not None:
                # Either a different payment_id, or the same payment_id with a
                # different amount than what was originally recorded.
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "order already has a recorded payment that does not match this request",
                    {"order_id": order_id},
                )
            status = order["status"]
            if status != "pending":
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot pay order in status {status}",
                    {"order_id": order_id, "status": status},
                )
            if amount_cents != order["total_cents"]:
                raise OrderError(
                    "AMOUNT_MISMATCH",
                    "amount_cents does not match order total_cents",
                    {"order_id": order_id, "expected": order["total_cents"], "actual": amount_cents},
                )
            now = self._call_clock()
            conn.execute(
                "UPDATE orders SET status = 'paid', payment_id = ?, amount_cents = ?, updated_at = ? "
                "WHERE order_id = ?",
                (payment_id, amount_cents, now, order_id),
            )
            return self._build_order_dict(conn, order_id)

    def cancel_order(self, order_id: str) -> dict:
        if not _is_nonempty_str(order_id):
            raise OrderError(
                "INVALID_INPUT", "order_id must be a non-empty, non-whitespace string", {"field": "order_id"}
            )
        with self._transaction() as conn:
            order = self._fetch_order_row(conn, order_id)
            if order is None:
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})
            status = order["status"]
            if status == "cancelled":
                return self._order_dict_from_row(conn, order)
            if status == "shipped":
                raise OrderError(
                    "INVALID_STATE", "cannot cancel a shipped order", {"order_id": order_id, "status": status}
                )
            items = conn.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?", (order_id,)
            ).fetchall()
            for item in items:
                conn.execute(
                    "INSERT INTO stock (sku, available) VALUES (?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET available = available + excluded.available",
                    (item["sku"], item["quantity"]),
                )
            now = self._call_clock()
            conn.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ? WHERE order_id = ?", (now, order_id)
            )
            return self._build_order_dict(conn, order_id)

    def ship_order(self, order_id: str) -> dict:
        if not _is_nonempty_str(order_id):
            raise OrderError(
                "INVALID_INPUT", "order_id must be a non-empty, non-whitespace string", {"field": "order_id"}
            )
        with self._transaction() as conn:
            order = self._fetch_order_row(conn, order_id)
            if order is None:
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})
            status = order["status"]
            if status == "shipped":
                return self._order_dict_from_row(conn, order)
            if status != "paid":
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot ship order in status {status}",
                    {"order_id": order_id, "status": status},
                )
            now = self._call_clock()
            conn.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ? WHERE order_id = ?", (now, order_id)
            )
            return self._build_order_dict(conn, order_id)

    def get_order(self, order_id: str) -> dict:
        if not _is_nonempty_str(order_id):
            raise OrderError(
                "INVALID_INPUT", "order_id must be a non-empty, non-whitespace string", {"field": "order_id"}
            )
        conn = self._conn
        row = self._fetch_order_row(conn, order_id)
        if row is None:
            raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})
        return self._order_dict_from_row(conn, row)


__all__ = ["OrderError", "OrderService"]

args.content:
"""Filesystem-backed durable outbox / lease queue (delivery spool).

All logical state lives in a single canonical JSON file (``state.json``)
inside a caller-supplied root directory. Every mutation acquires an
exclusive interprocess file lock, rereads and validates the current state,
writes a same-directory temporary file, fsyncs it, atomically replaces
``state.json``, and fsyncs the directory where supported.
"""

from __future__ import annotations

import dataclasses
import errno
import hmac
import json
import math
import os
import secrets
import time as _time
import uuid

try:
    import fcntl as _fcntl
except ImportError:  # pragma: no cover - platform dependent
    _fcntl = None

try:
    import msvcrt as _msvcrt
except ImportError:  # pragma: no cover - platform dependent
    _msvcrt = None


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = dict(details) if details is not None else {}


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value: object) -> bool:
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    return False


def _is_nonempty_str(value: object) -> bool:
    return isinstance(value, str) and value != "" and value.strip() != ""


def _json_safe(value: object, _depth: int = 0) -> bool:
    if _depth > 64:
        return False
    if value is None or isinstance(value, str):
        return True
    if isinstance(value, bool):
        return True
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, list):
        return all(_json_safe(item, _depth + 1) for item in value)
    if isinstance(value, dict):
        return all(isinstance(key, str) and _json_safe(val, _depth + 1) for key, val in value.items())
    return False


def _canonical_text(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def _no_duplicate_keys(pairs):
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate key: {key!r}")
        result[key] = value
    return result


def _require_positive_int(value: object, field: str) -> None:
    if not _is_int(value) or value <= 0:
        raise SpoolError("INVALID_INPUT", f"{field} must be a positive integer", {"field": field})


def _require_finite_nonnegative(value: object, field: str) -> None:
    if not _is_finite_number(value) or value < 0:
        raise SpoolError("INVALID_INPUT", f"{field} must be a finite number >= 0", {"field": field})


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        _require_positive_int(self.max_messages, "max_messages")
        _require_positive_int(self.max_payload_bytes, "max_payload_bytes")
        _require_positive_int(self.max_attempts, "max_attempts")
        _require_finite_nonnegative(self.lease_seconds, "lease_seconds")
        _require_finite_nonnegative(self.retry_delay, "retry_delay")
        if self.lease_seconds <= 0:
            raise SpoolError("INVALID_INPUT", "lease_seconds must be > 0", {"field": "lease_seconds"})


_TOP_FIELDS = frozenset({"schema_version", "next_sequence", "messages"})
_MESSAGE_FIELDS = frozenset(
    {
        "payload",
        "status",
        "available_at",
        "sequence",
        "attempts",
        "last_error",
        "worker_id",
        "lease_token",
        "expires_at",
    }
)
_STATUSES = frozenset({"pending", "leased", "acked", "dead"})


class _LockUnavailable(Exception):
    pass


def _ensure_nonempty(fh) -> None:
    fh.seek(0, os.SEEK_END)
    if fh.tell() == 0:
        fh.write(b"0")
        fh.flush()


def _try_lock(fh) -> None:
    if _fcntl is not None:
        try:
            _fcntl.flock(fh.fileno(), _fcntl.LOCK_EX | _fcntl.LOCK_NB)
        except OSError as exc:
            if exc.errno in (errno.EACCES, errno.EAGAIN, errno.EWOULDBLOCK, errno.EDEADLK):
                raise _LockUnavailable() from exc
            raise
        return
    if _msvcrt is not None:
        try:
            fh.seek(0)
            _msvcrt.locking(fh.fileno(), _msvcrt.LK_NBLCK, 1)
        except OSError as exc:
            raise _LockUnavailable() from exc
        return
    raise SpoolError("INTERNAL_ERROR", "no file locking primitive available on this platform", {})


def _try_unlock(fh) -> None:
    if _fcntl is not None:
        try:
            _fcntl.flock(fh.fileno(), _fcntl.LOCK_UN)
        except OSError:
            pass
        return
    if _msvcrt is not None:
        try:
            fh.seek(0)
            _msvcrt.locking(fh.fileno(), _msvcrt.LK_UNLCK, 1)
        except OSError:
            pass
        return


class _FileLock:
    def __init__(self, path: str, timeout: float):
        self._path = path
        self._timeout = float(timeout)
        self._fh = None

    def acquire(self) -> None:
        deadline = _time.monotonic() + self._timeout
        delay = 0.001
        while True:
            try:
                fh = open(self._path, "a+b")
            except FileNotFoundError:
                raise
            except OSError as exc:
                raise SpoolError("INTERNAL_ERROR", f"cannot open lock file: {exc}", {}) from exc
            try:
                _ensure_nonempty(fh)
                _try_lock(fh)
            except _LockUnavailable:
                fh.close()
                if _time.monotonic() >= deadline:
                    raise SpoolError("LOCK_TIMEOUT", "timed out waiting for the spool lock", {})
                _time.sleep(min(delay, 0.05))
                delay = min(delay * 2, 0.05)
                continue
            except SpoolError:
                fh.close()
                raise
            except OSError as exc:
                fh.close()
                raise SpoolError("INTERNAL_ERROR", f"failed to lock spool: {exc}", {}) from exc
            else:
                self._fh = fh
                return

    def release(self) -> None:
        if self._fh is None:
            return
        fh = self._fh
        self._fh = None
        try:
            _try_unlock(fh)
        finally:
            try:
                fh.close()
            except OSError:
                pass


class Spool:
    """Filesystem-backed lease spool."""

    _SCHEMA_VERSION = 1

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be a Limits instance", {"field": "limits"})
        if not _is_finite_number(lock_timeout) or lock_timeout < 0:
            raise SpoolError(
                "INVALID_INPUT", "lock_timeout must be a finite number >= 0", {"field": "lock_timeout"}
            )
        try:
            self._root = os.fspath(root)
        except TypeError as exc:
            raise SpoolError(
                "INVALID_INPUT", f"root must be a path-like object: {exc}", {"field": "root"}
            ) from exc
        self._clock = clock
        self._limits = limits
        self._lock_timeout = float(lock_timeout)
        self._failpoint = failpoint
        self._state_path = os.path.join(self._root, "state.json")
        self._lock_path = os.path.join(self._root, "state.lock")

    # -- dependency helpers ----------------------------------------------

    def _call_clock(self):
        try:
            value = self._clock()
        except Exception as exc:
            raise SpoolError("INVALID_DEPENDENCY", f"clock() raised: {exc}", {}) from exc
        if not _is_finite_number(value):
            raise SpoolError("INVALID_DEPENDENCY", "clock() must return a finite number", {})
        return value

    def _call_failpoint(self, name: str) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    # -- state (de)serialization ----------------------------------------------

    def _validate_state_shape(self, obj: object) -> dict:
        if not isinstance(obj, dict):
            raise SpoolError("CORRUPT_STATE", "state root must be an object", {})
        if set(obj.keys()) != _TOP_FIELDS:
            raise SpoolError("CORRUPT_STATE", "state has unknown or missing top-level fields", {})
        schema_version = obj["schema_version"]
        if not _is_int(schema_version) or schema_version != self._SCHEMA_VERSION:
            raise SpoolError("SCHEMA_MISMATCH", "unsupported schema_version", {})
        next_sequence = obj["next_sequence"]
        if not _is_int(next_sequence) or next_sequence < 1:
            raise SpoolError("CORRUPT_STATE", "invalid next_sequence", {})
        messages = obj["messages"]
        if not isinstance(messages, dict):
            raise SpoolError("CORRUPT_STATE", "messages must be an object", {})
        seen_sequences: set = set()
        for message_id, entry in messages.items():
            if not isinstance(message_id, str) or message_id == "":
                raise SpoolError("CORRUPT_STATE", "invalid message id", {})
            if not isinstance(entry, dict) or set(entry.keys()) != _MESSAGE_FIELDS:
                raise SpoolError("CORRUPT_STATE", "message has unknown or missing fields", {})
            status = entry["status"]
            if status not in _STATUSES:
                raise SpoolError("CORRUPT_STATE", "invalid message status", {})
            if not _json_safe(entry["payload"]):
                raise SpoolError("CORRUPT_STATE", "payload contains a non-JSON value", {})
            available_at = entry["available_at"]
            if not _is_finite_number(available_at):
                raise SpoolError("CORRUPT_STATE", "invalid available_at", {})
            sequence = entry["sequence"]
            if not _is_int(sequence) or sequence < 1 or sequence in seen_sequences:
                raise SpoolError("CORRUPT_STATE", "invalid or duplicate sequence", {})
            if sequence >= next_sequence:
                raise SpoolError("CORRUPT_STATE", "sequence inconsistent with next_sequence", {})
            seen_sequences.add(sequence)
            attempts = entry["attempts"]
            if not _is_int(attempts) or attempts < 0:
                raise SpoolError("CORRUPT_STATE", "invalid attempts", {})
            last_error = entry["last_error"]
            if last_error is not None and not isinstance(last_error, str):
                raise SpoolError("CORRUPT_STATE", "invalid last_error", {})
            worker_id = entry["worker_id"]
            lease_token = entry["lease_token"]
            expires_at = entry["expires_at"]
            if status == "leased":
                if not isinstance(worker_id, str) or worker_id.strip() == "":
                    raise SpoolError("CORRUPT_STATE", "leased message missing worker_id", {})
                if not isinstance(lease_token, str) or lease_token == "":
                    raise SpoolError("CORRUPT_STATE", "leased message missing lease_token", {})
                if not _is_finite_number(expires_at):
                    raise SpoolError("CORRUPT_STATE", "leased message missing expires_at", {})
            else:
                if worker_id is not None or lease_token is not None or expires_at is not None:
                    raise SpoolError("CORRUPT_STATE", "inconsistent status fields", {})
        return obj

    def _read_file_bytes(self, path: str) -> bytes:
        try:
            with open(path, "rb") as fh:
                return fh.read()
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to read state file: {exc}", {}) from exc

    def _read_state(self, *, require_initialized: bool):
        if not os.path.isfile(self._state_path):
            if require_initialized:
                raise SpoolError("NOT_INITIALIZED", "spool root has not been initialized", {})
            return None
        raw = self._read_file_bytes(self._state_path)
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise SpoolError("CORRUPT_STATE", f"state.json is not valid utf-8: {exc}", {}) from exc
        try:
            obj = json.loads(text, object_pairs_hook=_no_duplicate_keys)
        except ValueError as exc:
            raise SpoolError("CORRUPT_STATE", f"state.json is not valid JSON: {exc}", {}) from exc
        return self._validate_state_shape(obj)

    def _fsync_dir(self) -> None:
        try:
            fd = os.open(self._root, os.O_RDONLY)
        except OSError:
            return
        try:
            os.fsync(fd)
        except OSError:
            pass
        finally:
            os.close(fd)

    def _write_state_atomic(self, new_state: dict, tmp_holder: list) -> None:
        data = (_canonical_text(new_state) + "\n").encode("utf-8")
        tmp_name = f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp"
        tmp_path = os.path.join(self._root, tmp_name)
        tmp_holder.append(tmp_path)
        try:
            fh = open(tmp_path, "wb")
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to create temp file: {exc}", {}) from exc
        try:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        except OSError as exc:
            fh.close()
            raise SpoolError("INTERNAL_ERROR", f"failed to write temp file: {exc}", {}) from exc
        fh.close()
        self._call_failpoint("before_replace")
        try:
            os.replace(tmp_path, self._state_path)
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to replace state file: {exc}", {}) from exc
        tmp_holder.remove(tmp_path)
        self._call_failpoint("after_replace")
        self._fsync_dir()

    # -- locked mutation / read plumbing --------------------------------------

    def _locked_commit(self, mutate_fn, *, require_initialized: bool):
        lock = _FileLock(self._lock_path, self._lock_timeout)
        try:
            lock.acquire()
        except FileNotFoundError as exc:
            if require_initialized:
                raise SpoolError("NOT_INITIALIZED", "spool root has not been initialized", {}) from exc
            raise SpoolError("INTERNAL_ERROR", f"cannot access spool root: {exc}", {}) from exc
        tmp_holder: list = []
        try:
            self._call_failpoint("after_lock")
            state = self._read_state(require_initialized=require_initialized)
            try:
                new_state, result = mutate_fn(state)
            except SpoolError:
                raise
            except Exception as exc:
                raise SpoolError("INTERNAL_ERROR", f"unexpected error: {exc}", {}) from exc
            if new_state is not None:
                self._write_state_atomic(new_state, tmp_holder)
            return result
        finally:
            for path in list(tmp_holder):
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError:
                    pass
            lock.release()

    def _locked_read(self, fn):
        lock = _FileLock(self._lock_path, self._lock_timeout)
        try:
            lock.acquire()
        except FileNotFoundError as exc:
            raise SpoolError("NOT_INITIALIZED", "spool root has not been initialized", {}) from exc
        try:
            state = self._read_state(require_initialized=True)
            try:
                return fn(state)
            except SpoolError:
                raise
            except Exception as exc:
                raise SpoolError("INTERNAL_ERROR", f"unexpected error: {exc}", {}) from exc
        finally:
            lock.release()

    # -- public message projection --------------------------------------------

    def _public_message(self, message_id: str, entry: dict) -> dict:
        return {
            "message_id": message_id,
            "payload": entry["payload"],
            "status": entry["status"],
            "available_at": entry["available_at"],
            "sequence": entry["sequence"],
            "attempts": entry["attempts"],
            "last_error": entry["last_error"],
        }

    # -- public API -----------------------------------------------------------

    def initialize(self) -> dict:
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as exc:
            raise SpoolError("INTERNAL_ERROR", f"cannot create spool root: {exc}", {}) from exc

        def _mutate(state):
            if state is not None:
                raise SpoolError("ALREADY_INITIALIZED", "spool root is already initialized", {})
            fresh = {"schema_version": self._SCHEMA_VERSION, "next_sequence": 1, "messages": {}}
            return fresh, {"schema_version": self._SCHEMA_VERSION, "next_sequence": 1, "messages": {}}

        return self._locked_commit(_mutate, require_initialized=False)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        if not _is_nonempty_str(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string", {})
        if not _json_safe(payload):
            raise SpoolError("INVALID_INPUT", "payload must consist only of JSON-safe types", {})
        canonical_payload_text = _canonical_text(payload)
        payload_len = len(canonical_payload_text.encode("utf-8"))
        if payload_len > self._limits.max_payload_bytes:
            raise SpoolError(
                "CAPACITY_EXCEEDED",
                "payload exceeds max_payload_bytes",
                {"limit": self._limits.max_payload_bytes, "actual": payload_len},
            )
        if available_at is not None and not _is_finite_number(available_at):
            raise SpoolError("INVALID_INPUT", "available_at must be a finite number", {})

        def _mutate(state):
            messages = state["messages"]
            existing = messages.get(message_id)
            if existing is not None:
                existing_canonical = _canonical_text(existing["payload"])
                payload_matches = existing_canonical == canonical_payload_text
                available_matches = (
                    True if available_at is None else (existing["available_at"] == available_at)
                )
                if payload_matches and available_matches:
                    return None, self._public_message(message_id, existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    "message_id already enqueued with a different payload or available_at",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED", "max_messages exceeded", {"limit": self._limits.max_messages}
                )
            at_value = available_at if available_at is not None else self._call_clock()
            sequence = state["next_sequence"]
            entry = {
                "payload": json.loads(canonical_payload_text),
                "status": "pending",
                "available_at": at_value,
                "sequence": sequence,
                "attempts": 0,
                "last_error": None,
                "worker_id": None,
                "lease_token": None,
                "expires_at": None,
            }
            new_messages = dict(messages)
            new_messages[message_id] = entry
            new_state = {
                "schema_version": state["schema_version"],
                "next_sequence": sequence + 1,
                "messages": new_messages,
            }
            return new_state, self._public_message(message_id, entry)

        return self._locked_commit(_mutate, require_initialized=True)

    def claim(self, worker_id: str):
        if not _is_nonempty_str(worker_id):
            raise SpoolError("INVALID_INPUT", "worker_id must be a non-empty, non-whitespace string", {})

        def _mutate(state):
            now = self._call_clock()
            messages = state["messages"]
            best_key = None
            best_id = None
            for mid, entry in messages.items():
                if entry["status"] != "pending" or entry["available_at"] > now:
                    continue
                key = (entry["available_at"], entry["sequence"], mid)
                if best_key is None or key < best_key:
                    best_key = key
                    best_id = mid
            if best_id is None:
                return None, None
            entry = messages[best_id]
            token = secrets.token_hex(32)
            new_entry = dict(entry)
            new_entry["status"] = "leased"
            new_entry["attempts"] = entry["attempts"] + 1
            new_entry["worker_id"] = worker_id
            new_entry["lease_token"] = token
            new_entry["expires_at"] = now + self._limits.lease_seconds
            new_messages = dict(messages)
            new_messages[best_id] = new_entry
            new_state = {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": new_messages,
            }
            public = self._public_message(best_id, new_entry)
            public["lease_token"] = token
            return new_state, public

        return self._locked_commit(_mutate, require_initialized=True)

    def ack(self, message_id: str, lease_token: str) -> dict:
        if not _is_nonempty_str(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string", {})
        if not isinstance(lease_token, str) or lease_token == "":
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})

        def _mutate(state):
            messages = state["messages"]
            entry = messages.get(message_id)
            if entry is None:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            if entry["status"] != "leased" or not hmac.compare_digest(entry["lease_token"] or "", lease_token):
                raise SpoolError("UNAUTHORIZED", "lease token is missing or incorrect", {"message_id": message_id})
            new_entry = dict(entry)
            new_entry["status"] = "acked"
            new_entry["worker_id"] = None
            new_entry["lease_token"] = None
            new_entry["expires_at"] = None
            new_messages = dict(messages)
            new_messages[message_id] = new_entry
            new_state = {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": new_messages,
            }
            return new_state, self._public_message(message_id, new_entry)

        return self._locked_commit(_mutate, require_initialized=True)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        if not _is_nonempty_str(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string", {})
        if not isinstance(lease_token, str) or lease_token == "":
            raise SpoolError("INVALID_INPUT", "lease_token must be a non-empty string", {})
        if not isinstance(error, str) or error == "":
            raise SpoolError("INVALID_INPUT", "error must be a non-empty string", {})

        def _mutate(state):
            messages = state["messages"]
            entry = messages.get(message_id)
            if entry is None:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            if entry["status"] != "leased" or not hmac.compare_digest(entry["lease_token"] or "", lease_token):
                raise SpoolError("UNAUTHORIZED", "lease token is missing or incorrect", {"message_id": message_id})
            new_entry = dict(entry)
            new_entry["worker_id"] = None
            new_entry["lease_token"] = None
            new_entry["expires_at"] = None
            new_entry["last_error"] = error
            if entry["attempts"] >= self._limits.max_attempts:
                new_entry["status"] = "dead"
            else:
                now = self._call_clock()
                new_entry["status"] = "pending"
                new_entry["available_at"] = now + self._limits.retry_delay
            new_messages = dict(messages)
            new_messages[message_id] = new_entry
            new_state = {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": new_messages,
            }
            return new_state, self._public_message(message_id, new_entry)

        return self._locked_commit(_mutate, require_initialized=True)

    def recover(self) -> dict:
        def _mutate(state):
            now = self._call_clock()
            messages = state["messages"]
            new_messages = dict(messages)
            recovered = 0
            for mid, entry in messages.items():
                if entry["status"] == "leased" and now >= entry["expires_at"]:
                    new_entry = dict(entry)
                    new_entry["worker_id"] = None
                    new_entry["lease_token"] = None
                    new_entry["expires_at"] = None
                    if entry["attempts"] >= self._limits.max_attempts:
                        new_entry["status"] = "dead"
                    else:
                        new_entry["status"] = "pending"
                        new_entry["available_at"] = now
                    new_messages[mid] = new_entry
                    recovered += 1
            if recovered == 0:
                return None, {"recovered": 0}
            new_state = {
                "schema_version": state["schema_version"],
                "next_sequence": state["next_sequence"],
                "messages": new_messages,
            }
            return new_state, {"recovered": recovered}

        return self._locked_commit(_mutate, require_initialized=True)

    def get(self, message_id: str) -> dict:
        if not _is_nonempty_str(message_id):
            raise SpoolError("INVALID_INPUT", "message_id must be a non-empty, non-whitespace string", {})

        def _read(state):
            entry = state["messages"].get(message_id)
            if entry is None:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            return self._public_message(message_id, entry)

        return self._locked_read(_read)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None and status not in _STATUSES:
            raise SpoolError(
                "INVALID_INPUT", "status must be one of pending/leased/acked/dead", {"field": "status"}
            )

        def _read(state):
            items = []
            for mid, entry in state["messages"].items():
                if status is not None and entry["status"] != status:
                    continue
                items.append(self._public_message(mid, entry))
            items.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            return items

        return self._locked_read(_read)


__all__ = ["Limits", "Spool", "SpoolError"]

