"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time

from . import Limits, Spool, SpoolError


_REQUIRED_FIELDS = {
    "init": frozenset(),
    "enqueue": frozenset({"message_id", "payload"}),
    "claim": frozenset({"worker_id"}),
    "ack": frozenset({"message_id", "lease_token"}),
    "fail": frozenset({"message_id", "lease_token", "error"}),
    "recover": frozenset(),
    "show": frozenset({"message_id"}),
    "list": frozenset(),
}

_OPTIONAL_FIELDS = {
    "enqueue": frozenset({"available_at"}),
    "list": frozenset({"status"}),
}

_OMIT_ALLOWED = frozenset({"init", "recover", "list"})

_METHODS = {
    "init": "initialize",
    "enqueue": "enqueue",
    "claim": "claim",
    "ack": "ack",
    "fail": "fail",
    "recover": "recover",
    "show": "get",
    "list": "list_messages",
}


def _parse_argv(argv: list[str]):
    root = None
    rest: list[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--root":
            if i + 1 >= len(argv):
                return None, None
            root = argv[i + 1]
            i += 2
            continue
        if token.startswith("--root="):
            root = token[len("--root="):]
            i += 1
            continue
        rest.append(token)
        i += 1
    if root is None or len(rest) != 1:
        return None, None
    return root, rest[0]


def _read_input(command: str) -> dict:
    raw = sys.stdin.read()
    lines = raw.splitlines()
    if len(lines) == 0:
        if command in _OMIT_ALLOWED:
            return {}
        raise SpoolError("INVALID_INPUT", "stdin must contain exactly one non-empty line", {})
    if len(lines) > 1:
        raise SpoolError("INVALID_INPUT", "stdin must contain exactly one line", {})
    line = lines[0]
    if line.strip() == "":
        if command in _OMIT_ALLOWED:
            return {}
        raise SpoolError("INVALID_INPUT", "stdin line must be non-empty", {})
    try:
        value = json.loads(line)
    except ValueError as exc:
        raise SpoolError("INVALID_INPUT", f"invalid JSON: {exc}", {}) from exc
    if not isinstance(value, dict):
        raise SpoolError("INVALID_INPUT", "input must be a JSON object", {})
    return value


def _validate_fields(command: str, body: dict) -> None:
    required = _REQUIRED_FIELDS[command]
    optional = _OPTIONAL_FIELDS.get(command, frozenset())
    allowed = required | optional
    given = set(body.keys())
    if given - allowed:
        raise SpoolError("INVALID_INPUT", "unknown fields in input", {"command": command})
    if required - given:
        raise SpoolError("INVALID_INPUT", "missing required fields", {"command": command})


def _write(obj: dict) -> None:
    sys.stdout.write(json.dumps(obj, sort_keys=True, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")
    sys.stdout.flush()


def _error_envelope(code: str, message: str, details: dict) -> dict:
    return {"ok": False, "error": {"code": code, "message": message, "details": details or {}}}


def main(argv: list[str] | None = None) -> int:
    try:
        sys.stdin.reconfigure(encoding="utf-8")
    except Exception:
        pass
    argv = sys.argv[1:] if argv is None else list(argv)
    root, command = _parse_argv(argv)
    if root is None or command not in _METHODS:
        _write(_error_envelope("INVALID_INPUT", "invalid CLI invocation", {}))
        return 2
    try:
        body = _read_input(command)
        _validate_fields(command, body)
        spool = Spool(root, clock=time.time, limits=Limits(), lock_timeout=10.0, failpoint=None)
        method = getattr(spool, _METHODS[command])
        result = method(**body)
        _write({"ok": True, "result": result})
        return 0
    except SpoolError as exc:
        exit_code = 3 if exc.code in ("CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR") else 2
        _write(_error_envelope(exc.code, exc.message, exc.details))
        return exit_code
    except Exception as exc:
        _write(_error_envelope("INTERNAL_ERROR", "internal error", {"reason": str(exc)[:200]}))
        return 3


if __name__ == "__main__":
    sys.exit(main())

