"""Extra edge-case checks for order_fulfillment. Temporary, not part of the deliverable."""

from __future__ import annotations

import os
import tempfile

from src.order_fulfillment import OrderError, OrderService

FAIL = []


def check(cond, msg):
    if not cond:
        FAIL.append(msg)
        print("FAIL:", msg)
    else:
        print("ok:", msg)


def main():
    tmp = tempfile.mkdtemp(prefix="orderfulfillment_extra_")

    def raising_clock():
        raise RuntimeError("clock exploded")

    def raising_idf():
        raise RuntimeError("idf exploded")

    svc = OrderService(os.path.join(tmp, "a.db"), clock=raising_clock, id_factory=lambda: "x1")
    svc.set_stock("s", 5)
    try:
        svc.create_order("k1", [{"sku": "s", "quantity": 1, "unit_price_cents": 1}])
        check(False, "clock raising exception should surface as INVALID_DEPENDENCY")
    except OrderError as exc:
        check(exc.code == "INVALID_DEPENDENCY", f"clock exception -> INVALID_DEPENDENCY, got {exc.code}")

    svc2 = OrderService(os.path.join(tmp, "b.db"), clock=lambda: 1.0, id_factory=raising_idf)
    svc2.set_stock("s", 5)
    try:
        svc2.create_order("k1", [{"sku": "s", "quantity": 1, "unit_price_cents": 1}])
        check(False, "id_factory raising exception should surface as INVALID_DEPENDENCY")
    except OrderError as exc:
        check(exc.code == "INVALID_DEPENDENCY", f"id_factory exception -> INVALID_DEPENDENCY, got {exc.code}")

    # verify no stock reserved after either dependency failure
    svc3 = OrderService(os.path.join(tmp, "a.db"), clock=lambda: 2.0, id_factory=lambda: "recovered-1")
    o = svc3.create_order("k-recover", [{"sku": "s", "quantity": 5, "unit_price_cents": 1}])
    check(o["status"] == "pending", "stock was not reserved by the earlier clock-raising failed attempt")

    print()
    if FAIL:
        print(f"=== {len(FAIL)} FAILURES ===")
        for f in FAIL:
            print(" -", f)
    else:
        print("=== ALL ORDER_FULFILLMENT EXTRA CHECKS PASSED ===")
    return 1 if FAIL else 0


if __name__ == "__main__":
    raise SystemExit(main())

